TEMPLATE_B64 = ""

# ==========================================
# 유틸: EXIF 방향 정보에 따라 이미지를 바로 세움
# ==========================================
def fix_image_orientation(img: PILImage.Image) -> PILImage.Image:
    try:
        exif = img._getexif()
        if exif is None:
            return img
        orientation = exif.get(274)  # 274 = Orientation 태그
        rotate_map = {
            3: 180,
            6: 270,
            8: 90,
        }
        flip_map = {
            2: (True, False),
            4: (False, True),
            5: (True, False),   # flip then rotate
            7: (True, False),
        }
        rotate_after_flip = {5: 270, 7: 90}

        if orientation in rotate_map:
            img = img.rotate(rotate_map[orientation], expand=True)
        elif orientation in flip_map:
            h, v = flip_map[orientation]
            if h:
                img = img.transpose(PILImage.FLIP_LEFT_RIGHT)
            if v:
                img = img.transpose(PILImage.FLIP_TOP_BOTTOM)
            if orientation in rotate_after_flip:
                img = img.rotate(rotate_after_flip[orientation], expand=True)
    except Exception:
        pass
    return img

# ==========================================
# 유틸: 병합셀 기준셀 반환
# ==========================================
def get_writable_cell(ws, cell_str):
    cell = ws[cell_str]
    if isinstance(cell, MergedCell):
        for mr in ws.merged_cells.ranges:
            if cell.coordinate in mr:
                return ws.cell(row=mr.min_row, column=mr.min_col)
    return cell

# ==========================================
# 유틸: 열/행 범위 → 픽셀 크기 (소수점 유지)
# ==========================================
def range_pixel_size(ws, min_col, max_col, min_row, max_row):
    w = sum((ws.column_dimensions[get_column_letter(c)].width or 8.43) * 7.5
            for c in range(min_col, max_col + 1))
    h = sum((ws.row_dimensions[r].height or 15) * 1.333
            for r in range(min_row, max_row + 1))
    return int(w), int(h)

# ==========================================
# 유틸: 셀 문자열 → 병합범위 포함한 (min_col, max_col, min_row, max_row)
# 주의: 병합셀의 기준셀(첫번째 셀)은 MergedCell이 아닌 Cell 타입이므로
#       타입 체크 없이 항상 병합범위를 먼저 탐색해야 함
# ==========================================
def get_cell_range(ws, cell_str):
    cell = ws[cell_str]
    for mr in ws.merged_cells.ranges:
        if (mr.min_row <= cell.row <= mr.max_row and
                mr.min_col <= cell.column <= mr.max_col):
            return mr.min_col, mr.max_col, mr.min_row, mr.max_row
    return cell.column, cell.column, cell.row, cell.row

# ==========================================
# ★ 사진 삽입: TwoCellAnchor로 병합셀 전체 크기에 정확히 꽉 채움
# ==========================================
def insert_image_to_cell(ws, cell_str, img_source):
    try:
        img = PILImage.open(img_source)
        img = fix_image_orientation(img)
    except Exception:
        return

    min_col, max_col, min_row, max_row = get_cell_range(ws, cell_str)
    target_w, target_h = range_pixel_size(ws, min_col, max_col, min_row, max_row)
    target_w = max(target_w, 50)
    target_h = max(target_h, 50)

    resized = img.resize((target_w, target_h), PILImage.LANCZOS)
    buf = BytesIO()
    resized.save(buf, format='PNG')
    buf.seek(0)

    xl_img = OpenpyxlImage(buf)
    xl_img.width  = target_w
    xl_img.height = target_h

    # TwoCellAnchor로 정확히 셀 범위에 고정 (offset=0으로 경계에 딱 맞춤)
    anchor = TwoCellAnchor(editAs='twoCell')
    anchor._from = AnchorMarker(col=min_col - 1, colOff=0, row=min_row - 1, rowOff=0)
    anchor.to    = AnchorMarker(col=max_col,     colOff=0, row=max_row,     rowOff=0)
    xl_img.anchor = anchor
    ws.add_image(xl_img)

# ==========================================
# ★ 결재박스: D열 중간 ~ H열 끝
#   왼쪽 칸: "결\n재" (가운데 정렬), 이후: 담당/과장/부장/센터장
#   흰 바탕에 검은 텍스트, 외곽선만 검은색
# ==========================================
APPROVAL_ANCHOR_COL  = 4        # D열 (1-indexed, anchor 열)
APPROVAL_MAX_COL     = 8        # H열
APPROVAL_MIN_ROW, APPROVAL_MAX_ROW = 2, 4

def insert_approval_box(ws, approval_img_path=None):
    # D열 너비의 절반을 colOff으로 사용 → D 중간부터 시작
    d_w_px  = (ws.column_dimensions['D'].width or 8.43) * 7.5
    col_off_px = d_w_px / 2                          # D열 중간 오프셋 (px)
    col_off_emu = int(col_off_px * 9144)              # px → EMU

    # 이미지 너비: D절반 + E + F + G + H
    efgh_px = sum((ws.column_dimensions[c].width or 8.43) * 7.5 for c in 'EFGH')
    total_w = int(d_w_px / 2 + efgh_px)

    # 이미지 높이: row 2~4
    total_h = range_pixel_size(ws, 1, 1, APPROVAL_MIN_ROW, APPROVAL_MAX_ROW)[1]
    total_w = max(total_w, 180)
    total_h = max(total_h, 70)

    if approval_img_path is not None:
        # BytesIO(base64 디코딩) 또는 파일 경로 모두 지원
        try:
            if isinstance(approval_img_path, BytesIO):
                approval_img_path.seek(0)
                src = PILImage.open(approval_img_path).convert("RGB")
            else:
                src = PILImage.open(approval_img_path).convert("RGB")
        except Exception:
            src = None

        if src is not None:
            # 흰색 여백 자동 제거 (배경색 기준 crop)
            import numpy as np
            arr = np.array(src)
            mask = ~((arr[:,:,0] > 240) & (arr[:,:,1] > 240) & (arr[:,:,2] > 240))
            rows = np.any(mask, axis=1)
            cols = np.any(mask, axis=0)
            if rows.any() and cols.any():
                rmin, rmax = np.where(rows)[0][[0, -1]]
                cmin, cmax = np.where(cols)[0][[0, -1]]
                src = src.crop((cmin, rmin, cmax + 1, rmax + 1))
            src = src.resize((total_w, total_h), PILImage.LANCZOS)
            buf = BytesIO()
            src.save(buf, format='PNG')
        else:
            approval_img_path = None  # 실패 시 자동생성으로 fallback
    else:
        # 폰트 (19pt) — 한글 지원 경로 우선순위 순으로 시도
        font_size = 19
        font = None
        for fp in [
            "/usr/share/fonts/opentype/noto/NotoSansCJK-Regular.ttc",
            "/usr/share/fonts/truetype/noto/NotoSansCJK-Regular.ttc",
            "/usr/share/fonts/opentype/noto/NotoSansCJK-Bold.ttc",
        ]:
            for idx in [0, 1, 2]:
                try:
                    font = ImageFont.truetype(fp, font_size, index=idx)
                    # 실제 한글 렌더링 가능 여부 확인
                    test_img = PILImage.new("RGB", (50, 30), (255,255,255))
                    test_draw = ImageDraw.Draw(test_img)
                    test_draw.text((0, 0), "결", font=font, fill=(0,0,0))
                    import numpy as np
                    arr = np.array(test_img)
                    if arr.min() < 200:  # 실제로 픽셀이 찍혔으면 OK
                        break
                    font = None
                except Exception:
                    font = None
            if font is not None:
                break
        if font is None:
            font = ImageFont.load_default()

        approval_labels = ["담당", "과장", "부장", "센터장"]
        n        = len(approval_labels)
        header_h = int(total_h * 0.38)

        # 완전 흰 바탕 (RGBA로 투명 없이 흰색)
        img  = PILImage.new("RGB", (total_w, total_h), (255, 255, 255))
        draw = ImageDraw.Draw(img)

        # 전체 흰 채우기 (혹시 남은 이전 픽셀 제거)
        draw.rectangle([0, 0, total_w, total_h], fill=(255, 255, 255))

        # ── 왼쪽 "결재" 칸: 오른쪽 담당/과장/부장/센터장 각 칸의 절반 너비 ──
        right_w   = total_w  # 임시 계산용
        each_cell = right_w // (n + 0.5)          # 4칸 + 결재칸(0.5) = 4.5등분
        label_w   = int(each_cell * 0.5)          # 결재칸 = 일반칸의 절반
        right_w   = total_w - label_w             # 담당~센터장 영역 실제 너비

        # 결재 칸: 흰 배경 + 검은 테두리
        draw.rectangle([0, 0, label_w - 1, total_h - 1],
                       fill=(255, 255, 255), outline="black", width=1)

        # "결" / "재" 세로 가운데 정렬 — 검은 텍스트
        for li, ch in enumerate(["결", "재"]):
            try:
                bb = draw.textbbox((0, 0), ch, font=font)
                tw, th = bb[2] - bb[0], bb[3] - bb[1]
            except Exception:
                tw, th = font_size, font_size + 2
            slot_h = total_h // 2
            tx = (label_w - tw) // 2
            ty = li * slot_h + (slot_h - th) // 2
            draw.text((tx, ty), ch, fill=(0, 0, 0), font=font)

        # ── 오른쪽: 담당/과장/부장/센터장 칸들 — 흰 배경 + 검은 테두리 ──
        cell_w = right_w // n
        for i, lbl in enumerate(approval_labels):
            x0 = label_w + i * cell_w
            x1 = label_w + (i + 1) * cell_w if i < n - 1 else total_w

            # 흰 배경으로 채우고 검은 테두리
            draw.rectangle([x0, 0, x1 - 1, total_h - 1],
                           fill=(255, 255, 255), outline="black", width=1)
            draw.line([x0, header_h, x1, header_h], fill=(0, 0, 0), width=1)

            try:
                bb = draw.textbbox((0, 0), lbl, font=font)
                tw, th = bb[2] - bb[0], bb[3] - bb[1]
            except Exception:
                tw, th = font_size * len(lbl), font_size + 2

            # 검은 텍스트
            draw.text(
                (x0 + (x1 - x0 - tw) // 2, (header_h - th) // 2),
                lbl, fill=(0, 0, 0), font=font
            )

        # 외곽 테두리 (검은색, 두께 2)
        draw.rectangle([0, 0, total_w - 1, total_h - 1],
                       outline=(0, 0, 0), width=2)

        buf = BytesIO()
        img.save(buf, format='PNG')

    # 위아래 여백 8px
    row_pad_px  = 8
    row_pad_emu = int(row_pad_px * 9144)
    padded_h    = max(total_h - row_pad_px * 2, 40)

    buf.seek(0)
    padded_img = PILImage.open(buf).resize((total_w, padded_h), PILImage.LANCZOS)
    padded_buf = BytesIO()
    padded_img.save(padded_buf, format='PNG')
    padded_buf.seek(0)

    xl_img        = OpenpyxlImage(padded_buf)
    xl_img.width  = total_w
    xl_img.height = padded_h

    # D열 중간(colOff)에서 시작, 위아래 여백(rowOff)
    anchor = TwoCellAnchor(editAs='twoCell')
    anchor._from = AnchorMarker(col=APPROVAL_ANCHOR_COL - 1, colOff=col_off_emu,
                                row=APPROVAL_MIN_ROW - 1,    rowOff=row_pad_emu)
    anchor.to    = AnchorMarker(col=APPROVAL_MAX_COL,        colOff=0,
                                row=APPROVAL_MAX_ROW,        rowOff=-row_pad_emu)
    xl_img.anchor = anchor
    ws.add_image(xl_img)


import json
import sys

# ==========================================
# exe / py 모두 대응: 실행파일 기준 경로
# ==========================================
if getattr(sys, 'frozen', False):
    BASE_DIR = os.path.dirname(sys.executable)   # .exe 옆 폴더
else:
    BASE_DIR = os.path.dirname(os.path.abspath(__file__))

CONFIG_FILE = os.path.join(BASE_DIR, "config.json")

# ── 기본값 (config.json이 없을 때 사용) ──────────────
DEFAULT_CONFIG = {
    "name":       "임태진",
    "position":   "일자리담당자",
    "bu_input":   "공원자연지킴이(영종)\n시니어바람개비보안관(영종)",
    "dest_input": (
        "구석말공원\n넙디공원\n달빛공원\n배곶공원\n별볓공원\n"
        "영마루공원\n운남공원\n하늘체육공원\n넙디마을\n"
        "중구2청사버스정류장\n영종1동주민센터\n중산고등학교\n"
        "하늘고요수목원(가평)"
    ),
    "purp_input": (
        "활동일지 교환 및 청소물품 배부\n"
        "모니터링 및 청소물품 배부\n"
        "문화활동"
    ),
}

def load_config():
    if os.path.exists(CONFIG_FILE):
        try:
            with open(CONFIG_FILE, 'r', encoding='utf-8') as f:
                data = json.load(f)
                # 혹시 누락된 키는 기본값으로 보완
                for k, v in DEFAULT_CONFIG.items():
                    data.setdefault(k, v)
                return data
        except Exception:
            pass
    # config.json 없으면 기본값 그대로 반환 (저장하지 않음)
    return dict(DEFAULT_CONFIG)

def save_config(cfg):
    try:
        with open(CONFIG_FILE, 'w', encoding='utf-8') as f:
            json.dump(cfg, f, ensure_ascii=False, indent=2)
        return True
    except Exception as e:
        return str(e)

cfg = load_config()

# ==========================================
# 유틸: 결재 이미지 base64 인코딩/디코딩
# ==========================================
import base64

def encode_image_to_b64(file_obj) -> str:
    return base64.b64encode(file_obj.read()).decode('utf-8')

def decode_b64_to_bytesio(b64_str: str) -> BytesIO:
    return BytesIO(base64.b64decode(b64_str))

# ==========================================
# 1. 사이드바
# ==========================================
position_options = ["일자리담당자", "주임", "대리", "과장", "부장", "센터장"]

with st.sidebar:
    st.header("⚙️ 기본 설정")
    st.caption("설정 후 💾 저장 버튼을 누르면 다음에도 유지됩니다.")

    default_name = st.text_input("성명 (기본값)", value=cfg.get("name", ""))
    default_position = st.selectbox(
        "직위 선택", position_options,
        index=position_options.index(cfg.get("position", "일자리담당자"))
        if cfg.get("position", "일자리담당자") in position_options else 0
    )

    st.subheader("목록 입력 (한 줄에 한 항목)")
    bu_input   = st.text_area("사업단명 (최대 5개)",  cfg.get("bu_input", ""),   height=120)
    dest_input = st.text_area("출장지 (최대 20개)",   cfg.get("dest_input", ""), height=200)
    purp_input = st.text_area("출장목적 (최대 20개)", cfg.get("purp_input", ""), height=200)

    # ── 결재 이미지 설정 ───────────────────────────────
    st.subheader("🖊️ 결재란 이미지 설정")
    st.caption("없으면 자동 생성됩니다. 저장하면 다음에도 유지됩니다.")

    saved_approval_b64 = cfg.get("approval_b64", "")

    # 현재 저장된 이미지 미리보기
    if saved_approval_b64:
        st.success("✅ 결재 이미지 저장됨")
        st.image(decode_b64_to_bytesio(saved_approval_b64), caption="현재 결재 이미지", use_container_width=True)
        if st.button("🗑️ 결재 이미지 삭제", use_container_width=True):
            cfg["approval_b64"] = ""
            save_config(cfg)
            st.rerun()
    else:
        st.info("ℹ️ 결재 이미지 없음 → 자동 생성")

    approval_upload = st.file_uploader(
        "결재란 이미지 업로드 (png/jpg)",
        type=['png', 'jpg', 'jpeg'],
        key="approval_upload"
    )

    if st.button("💾 설정 저장", use_container_width=True):
        new_approval_b64 = saved_approval_b64
        if approval_upload is not None:
            approval_upload.seek(0)
            new_approval_b64 = encode_image_to_b64(approval_upload)

        result = save_config({
            "name":         default_name,
            "position":     default_position,
            "bu_input":     bu_input,
            "dest_input":   dest_input,
            "purp_input":   purp_input,
            "approval_b64": new_approval_b64,
        })
        if result is True:
            st.success("✅ 저장 완료! 다음 실행 시에도 유지됩니다.")
            st.rerun()
        else:
            st.error(f"❌ 저장 실패: {result}")

bu_list   = [x.strip() for x in bu_input.split("\n")   if x.strip()][:5]
